using Ember.Core;
using Ember.UI;
using Game.UI;
using System;
using Cysharp.Threading.Tasks;
using Game.SceneFlow;
using UnityEngine.SceneManagement;
using Game.LaneDefense;

namespace Game.State
{
    /// <summary>
    /// 游戏层 GameplayState 子类 —— override 框架钩子，注入业务逻辑。
    ///
    /// <b>进入玩法 → 打开游戏内 UI：</b>
    /// <see cref="OnGameplayEnter"/> 在场景加载完成后调用，打开 InGameUI。
    ///
    /// <b>退出玩法 → 关闭所有 UI：</b>
    /// <see cref="OnGameplayExit"/> 在离开玩法前调用，清理 UI。
    /// </summary>
    public class GameGameplayState : GameplayState
    {
        private GameSceneSession _sceneSession;
        protected override void OnGameplayPause() { base.OnGameplayPause(); LaneDefenseModule.Instance.SetSuspended(true); }
        protected override void OnGameplayResume() { base.OnGameplayResume(); LaneDefenseModule.Instance.SetSuspended(false); }

        public override async UniTask PrepareEnterAsync(SceneTransitionContext request)
        {
            var scene = SceneManager.GetSceneByPath(request.ToScene);
            if (!scene.IsValid()) scene = SceneManager.GetSceneByName(request.ToScene);
            object sceneArgs = request.Args;
#if UNITY_EDITOR
            string workbenchLevel = UnityEditor.SessionState.GetString("LaneDefense.WorkbenchLevel", "");
            if (sceneArgs == null && !string.IsNullOrEmpty(workbenchLevel))
            {
                sceneArgs = UnityEditor.AssetDatabase.LoadAssetAtPath<LaneDefenseLevel>(workbenchLevel);
                UnityEditor.SessionState.EraseString("LaneDefense.WorkbenchLevel");
            }
#endif
            var candidate = await GameSceneScope.Require(scene).PrepareAsync(
                request.Operation.RequestId, sceneArgs, request.Cancellation);
            request.PreparedArgs = candidate;
            candidate.ReleaseOnFailedTransitionAsync(request.Operation).Forget();
        }

        public override UniTask AbortPrepareAsync(SceneTransitionContext request)
        {
            (request.PreparedArgs as GameSceneSession)?.Dispose();
            return UniTask.CompletedTask;
        }

        // [EmberManaged:begin OnGameplayEnter]
        protected override void OnGameplayEnter(object args)
        // [EmberManaged:end]
        {
            base.OnGameplayEnter(args);
            _sceneSession = args as GameSceneSession
                ?? throw new InvalidOperationException("Gameplay 必须通过请求级场景准备进入。");
            try
            {
                _sceneSession.Start();
                EUIManager.Instance.ShowMainPage(GamePages.EUILaneBattleHUD);
            }
            catch { _sceneSession.Dispose(); _sceneSession = null; throw; }
        }

        // [EmberManaged:begin OnGameplayExit]
        protected override void OnGameplayExit()
        // [EmberManaged:end]
        {
            try { _sceneSession?.Dispose(); }
            finally
            {
                _sceneSession = null;
                EUIManager.Instance.CloseAllPopups();
                EUIManager.Instance.ClosePageByDef(GamePages.EUILaneBattleHUD);
                base.OnGameplayExit();
            }
        }
    }
}
